typedef struct { char subject[512]; char scope[512]; } Closure;
typedef struct { char id[512]; } Identity;
static const char *arg(int argc,char **argv,const char *name){for(int i=2;i+1<argc;i++)if(!strcmp(argv[i],name))return argv[i+1];return NULL;}
static char *read_all(const char *path,size_t *n){FILE*f=fopen(path,"rb");char*b=NULL;long z;if(!f)return NULL;if(fseek(f,0,SEEK_END)||((z=ftell(f))<0)||fseek(f,0,SEEK_SET)){fclose(f);return NULL;}b=malloc((size_t)z+1);if(!b){fclose(f);return NULL;}if(z&&fread(b,1,(size_t)z,f)!=(size_t)z){free(b);fclose(f);return NULL;}b[z]=0;fclose(f);if(n)*n=(size_t)z;return b;}
static int sql(sqlite3*d,const char*q){char*e=NULL;int rc=sqlite3_exec(d,q,NULL,NULL,&e);if(rc!=SQLITE_OK){fprintf(stderr,"sqlite: %s\n",e?e:"error");sqlite3_free(e);return 0;}return 1;}
static void jt(const char*s){putchar('"');for(const unsigned char*p=(const unsigned char*)(s?s:"");*p;p++){if(*p=='"'||*p=='\\'){putchar('\\');putchar(*p);}else if(*p<32)printf("\\u%04x",*p);else putchar(*p);}putchar('"');}
static uint64_t hadd(uint64_t h,const char*s){for(const unsigned char*p=(const unsigned char*)(s?s:"");*p;p++){h^=*p;h*=1099511628211ULL;}h^=0xff;return h*1099511628211ULL;}
static int ensure_dir(const char*p){return p&&*p&&(mkdir(p,0750)==0||errno==EEXIST);}
static int run_capture(const char*bin,char*const av[],const char*path){int fd,status=0;pid_t p;if(!bin||!*bin||!path||(fd=open(path,O_WRONLY|O_CREAT|O_TRUNC,0640))<0)return 0;p=fork();if(p<0){close(fd);return 0;}if(!p){if(dup2(fd,STDOUT_FILENO)<0)_exit(127);close(fd);execv(bin,av);_exit(127);}if(waitpid(p,&status,0)<0){close(fd);return 0;}if(fsync(fd)){close(fd);return 0;}close(fd);return WIFEXITED(status)&&WEXITSTATUS(status)==0;}
static int has_id(Identity*a,int n,const char*id){for(int i=0;i<n;i++)if(!strcmp(a[i].id,id))return 1;return 0;}
static int old_ids(sqlite3*d,const char*s,const char*p,Identity*out,int cap){sqlite3_stmt*q=NULL;int n=0;if(sqlite3_prepare_v2(d,"SELECT dependency_ref FROM closure_dependency WHERE subject=?1 AND scope=?2 AND basis='external_candidate' AND dependency_ref LIKE 'external:%' ORDER BY dependency_ref",-1,&q,NULL)!=SQLITE_OK)return -1;sqlite3_bind_text(q,1,s,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,p,-1,SQLITE_TRANSIENT);while(sqlite3_step(q)==SQLITE_ROW&&n<cap){const char*v=(const char*)sqlite3_column_text(q,0);if(v)snprintf(out[n++].id,sizeof(out[n].id),"%s",v);}sqlite3_finalize(q);return n;}
static int closure_ids(sqlite3*d,const char*body,Identity*out,int cap){sqlite3_stmt*q=NULL;int n=0;const char*sqlq="SELECT DISTINCT id FROM (SELECT json_extract(c.value,'$.identity') id FROM json_each(?1,'$.pack_demands') d,json_each(d.value,'$.candidate_groups') g,json_each(g.value,'$.candidates') c UNION ALL SELECT json_extract(c.value,'$.identity') FROM json_each(?1,'$.world_demands') w,json_each(w.value,'$.dependencies') x,json_each(x.value,'$.candidates') c) WHERE id IS NOT NULL AND id<>'' ORDER BY id";if(sqlite3_prepare_v2(d,sqlq,-1,&q,NULL)!=SQLITE_OK)return -1;sqlite3_bind_text(q,1,body,-1,SQLITE_TRANSIENT);while(sqlite3_step(q)==SQLITE_ROW&&n<cap){const char*v=(const char*)sqlite3_column_text(q,0);if(v)snprintf(out[n++].id,sizeof(out[n].id),"%s",v);}sqlite3_finalize(q);return n;}
static int write_handoff(sqlite3*a,const char*dir,const char*delta,const char*id){sqlite3_stmt*q=NULL;const char*owner=NULL,*kind=NULL,*lower=NULL;char sub[1024],dest[1200],tmp[1240];FILE*f=NULL;int created=0;if(sqlite3_prepare_v2(a,"SELECT owner_ref,candidate_kind,lowerer_ref FROM candidate_advertisement WHERE identity=?1",-1,&q,NULL)!=SQLITE_OK)return -1;sqlite3_bind_text(q,1,id,-1,SQLITE_TRANSIENT);if(sqlite3_step(q)==SQLITE_ROW){owner=(const char*)sqlite3_column_text(q,0);kind=(const char*)sqlite3_column_text(q,1);lower=(const char*)sqlite3_column_text(q,2);if(owner&&kind&&lower&&!strcmp(kind,"external_occurrence")&&!strcmp(lower,"MaterialCompiler:external")){if(!ensure_dir(dir)||snprintf(sub,sizeof(sub),"%s/MaterialCompiler-external",dir)>=(int)sizeof(sub)||!ensure_dir(sub)||snprintf(dest,sizeof(dest),"%s/%016llx.json",sub,(unsigned long long)hadd(hadd(1469598103934665603ULL,delta),id))>=(int)sizeof(dest)){sqlite3_finalize(q);return -1;}if(access(dest,F_OK)){if(snprintf(tmp,sizeof(tmp),"%s.tmp",dest)>=(int)sizeof(tmp)||(f=fopen(tmp,"w"))==NULL){sqlite3_finalize(q);return -1;}fprintf(f,"{\"schema\":\"bonfyre-lowering-handoff.v1\",\"delta_id\":\"scoped-respecialize:%s\",\"identity\":\"%s\",\"candidate_kind\":\"external_occurrence\",\"owner_ref\":\"%s\",\"lowerer_ref\":\"MaterialCompiler:external\",\"truth\":\"newly_selected_dependency_cut_only\"}\n",delta,id,owner);if(fclose(f)||rename(tmp,dest)){remove(tmp);sqlite3_finalize(q);return -1;}created=1;}}}sqlite3_finalize(q);return created;}
static int seen(sqlite3*d,const char*delta,const char*s,const char*p){sqlite3_stmt*q=NULL;int yes=0;if(sqlite3_prepare_v2(d,"SELECT 1 FROM scoped_respecialize_receipt WHERE delta_id=?1 AND subject=?2 AND scope=?3",-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(q,1,delta,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,s,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,3,p,-1,SQLITE_TRANSIENT);yes=sqlite3_step(q)==SQLITE_ROW;sqlite3_finalize(q);return yes;}
static int receipt(sqlite3*d,const char*delta,const char*s,const char*p,const char*closure,int added){sqlite3_stmt*q=NULL;int ok=0;if(sqlite3_prepare_v2(d,"INSERT INTO scoped_respecialize_receipt(delta_id,subject,scope,closure_path,new_external_candidates,processed_at) VALUES(?1,?2,?3,?4,?5,?6)",-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(q,1,delta,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,s,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,3,p,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,4,closure,-1,SQLITE_TRANSIENT);sqlite3_bind_int(q,5,added);sqlite3_bind_int64(q,6,(sqlite3_int64)time(NULL));ok=sqlite3_step(q)==SQLITE_DONE;sqlite3_finalize(q);return ok;}

int main(int argc,char**argv){const char*frontier=arg(argc,argv,"--frontier-db"),*address=arg(argc,argv,"--address-db"),*delta_path=arg(argc,argv,"--delta"),*demand=arg(argc,argv,"--scoped-demand"),*frontier_bin=arg(argc,argv,"--scoped-frontier"),*handoffs=arg(argc,argv,"--handoff-dir"),*closure_dir=arg(argc,argv,"--closure-dir"),*conditions=arg(argc,argv,"--condition-db"),*limit_raw=arg(argc,argv,"--limit");sqlite3*d=NULL,*a=NULL;sqlite3_stmt*q=NULL,*meta=NULL;Closure *rows=NULL;Identity *old=NULL,*now=NULL;char*body=NULL,*delta=NULL;size_t n=0;int count=0,processed=0,already=0,new_external=0,dispatched=0,limit=limit_raw?atoi(limit_raw):256;
 /* These buffers total roughly eight megabytes at the bounded 4096 closure
  * limit.  They used to be automatic arrays, so even `--help` reserved them
  * before its argument refusal and overflowed the default macOS thread stack.
  * Their size is data-plane capacity, not call-frame state: keep the cap but
  * own it explicitly and release it on both terminal paths. */
 enum{SP_APPLY};static const BfCommandEntry respecialize_commands[]={{"apply",SP_APPLY,0,NULL},};const BfCommandEntry*command=argc<2?NULL:bf_command_lookup(respecialize_commands,sizeof(respecialize_commands)/sizeof(respecialize_commands[0]),argv[1]);
 if(argc<2||!command||command->id!=SP_APPLY||!frontier||!address||!delta_path||!demand||!frontier_bin||!handoffs||!closure_dir){fputs("usage: bonfyre-scoped-respecialize apply --frontier-db DB --address-db DB --delta JSON --scoped-demand BIN --scoped-frontier BIN --handoff-dir DIR --closure-dir DIR [--condition-db DB] [--limit N]\n",stderr);return 2;}
 rows=calloc(4096,sizeof(*rows));old=calloc(4096,sizeof(*old));now=calloc(4096,sizeof(*now));if(!rows||!old||!now)goto fail;
 if(limit<1)limit=1;if(limit>4096)limit=4096;if(!ensure_dir(handoffs)||!ensure_dir(closure_dir)||sqlite3_open(frontier,&d)!=SQLITE_OK||sqlite3_open_v2(address,&a,SQLITE_OPEN_READONLY,NULL)!=SQLITE_OK||!sql(d,"PRAGMA journal_mode=WAL;CREATE TABLE IF NOT EXISTS scoped_respecialize_receipt(delta_id TEXT NOT NULL,subject TEXT NOT NULL,scope TEXT NOT NULL,closure_path TEXT NOT NULL,new_external_candidates INTEGER NOT NULL,processed_at INTEGER NOT NULL,PRIMARY KEY(delta_id,subject,scope));"))goto fail;if(!(body=read_all(delta_path,&n)))goto fail;
 if(sqlite3_prepare_v2(d,"SELECT json_extract(?1,'$.delta_id')",-1,&meta,NULL)!=SQLITE_OK)goto fail;sqlite3_bind_text(meta,1,body,(int)n,SQLITE_TRANSIENT);if(sqlite3_step(meta)==SQLITE_ROW&&sqlite3_column_text(meta,0))delta=strdup((const char*)sqlite3_column_text(meta,0));sqlite3_finalize(meta);meta=NULL;if(!delta||!*delta)goto fail;
 if(sqlite3_prepare_v2(d,"WITH writes(ref) AS (SELECT value FROM json_each(?1,'$.writes')) SELECT DISTINCT c.subject,c.scope FROM closure_dependency c JOIN writes w ON w.ref=c.dependency_ref ORDER BY c.subject,c.scope LIMIT ?2",-1,&q,NULL)!=SQLITE_OK)goto fail;sqlite3_bind_text(q,1,body,(int)n,SQLITE_TRANSIENT);sqlite3_bind_int(q,2,limit);while(sqlite3_step(q)==SQLITE_ROW&&count<4096){const char*s=(const char*)sqlite3_column_text(q,0),*p=(const char*)sqlite3_column_text(q,1);if(!s||!p||snprintf(rows[count].subject,sizeof(rows[count].subject),"%s",s)>=(int)sizeof(rows[count].subject)||snprintf(rows[count].scope,sizeof(rows[count].scope),"%s",p)>=(int)sizeof(rows[count].scope))goto fail;count++;}sqlite3_finalize(q);q=NULL;
 for(int i=0;i<count;i++){int on,nn,added=0;char closure[1200],track_out[1240];uint64_t h=hadd(hadd(hadd(1469598103934665603ULL,delta),rows[i].subject),rows[i].scope);if(seen(d,delta,rows[i].subject,rows[i].scope)){already++;continue;}on=old_ids(d,rows[i].subject,rows[i].scope,old,4096);if(on<0)goto fail;if(snprintf(closure,sizeof(closure),"%s/closure-%016llx.json",closure_dir,(unsigned long long)h)>=(int)sizeof(closure)||snprintf(track_out,sizeof(track_out),"%s.track",closure)>=(int)sizeof(track_out))goto fail;char*base[]={(char*)demand,"resolve","--db",(char*)address,"--subject",rows[i].subject,"--scope",rows[i].scope,NULL};char*with_conditions[]={(char*)demand,"resolve","--db",(char*)address,"--subject",rows[i].subject,"--scope",rows[i].scope,"--condition-db",(char*)conditions,NULL};if(!run_capture(demand,conditions?with_conditions:base,closure))goto fail;char*closure_body=read_all(closure,NULL);if(!closure_body)goto fail;nn=closure_ids(d,closure_body,now,4096);free(closure_body);if(nn<0)goto fail;for(int j=0;j<nn;j++)if(!has_id(old,on,now[j].id)){int hr=write_handoff(a,handoffs,delta,now[j].id);if(hr<0)goto fail;added++;new_external++;if(hr>0)dispatched++;}char*track[]={(char*)frontier_bin,"track","--db",(char*)frontier,"--address-db",(char*)address,"--closure",closure,NULL};if(!run_capture(frontier_bin,track,track_out)||!receipt(d,delta,rows[i].subject,rows[i].scope,closure,added))goto fail;processed++;}
 fputs("{\"delta_id\":",stdout);jt(delta);printf(",\"affected_closures\":%d,\"processed\":%d,\"already_processed\":%d,\"new_external_candidates\":%d,\"material_handoffs_dispatched\":%d,\"truth\":\"incremental_respecialization_new_sources_only\",\"cannot_infer\":[\"recomputed closure -> authority\",\"existing external candidate -> new observation demand\",\"new external candidate -> admitted observation\"]}\n",count,processed,already,new_external,dispatched);sqlite3_close(a);sqlite3_close(d);free(rows);free(old);free(now);free(body);free(delta);return 0;
fail:sqlite3_finalize(q);sqlite3_finalize(meta);if(a)sqlite3_close(a);if(d)sqlite3_close(d);free(rows);free(old);free(now);free(body);free(delta);return 1;}
